"""24-stage curriculum. Original database IDs remain stable across this expansion."""

def sequence(prompt, cards, answer, explanation, hint):
    return dict(kind='sequence',prompt=prompt,cards=cards,answer=answer,explanation=explanation,hint=hint)
def sort_task(prompt,cards,categories,answer,explanation,hint):
    return dict(kind='sort',prompt=prompt,cards=cards,categories=categories,answer=answer,explanation=explanation,hint=hint)
def scenario(prompt,context,options,answer,explanation,hint):
    return dict(kind='scenario',prompt=prompt,context=context,options=options,answer=answer,explanation=explanation,hint=hint)
def program(prompt,start,goal,walls,answer,hint,palette=None,initial=None,max_commands=12):
    return dict(kind='program',prompt=prompt,size=5,start=start,goal=goal,walls=walls,
      palette=palette or ['E','S','W','N'],initial=initial or [],max_commands=max_commands,answer=answer,
      hint=hint,explanation='ไล่ตำแหน่งทีละคำสั่ง ห้ามออกนอกตารางหรือเดินทับก้อนหิน และต้องหยุดตรงธงเมื่อจบคำสั่งทั้งหมด')
def chart(prompt,records,categories,answer,explanation,hint):
    return dict(kind='chart',prompt=prompt,records=records,categories=categories,answer=answer,explanation=explanation,hint=hint)

